// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.wakewordimport timber.log.Timberimport android.content.Contextimport com.roshan.persona.voice.capture.CircularAudioBufferimport java.lang.reflect.Methodimport java.util.concurrent.atomic.AtomicBoolean/** * NOUS — Hardware Wake Word Detector (Tier 1: DSP). * * Wraps Android's SoundTrigger API to offload "Hey NOUS" detection to the * Qualcomm Hexagon / MediaTek APU ultra-low-power audio DSP. While the DSP * listens, the application CPU stays asleep — battery drain is < 0.5 %/hour. * * ## API Availability * * The SoundTrigger classes (`android.hardware.soundtrigger.SoundTrigger`) * were part of the public SDK through API 33. Starting from API 34, they * were moved to a mainline module (APEX) and are no longer in the public * `android.jar`. However, they ARE available at runtime on most devices. * * This class uses **reflection** to access the SoundTrigger API at runtime. * This is the standard Android pattern for accessing system APIs that exist * on the device but are not in the public SDK. If the API is not available * (older device, custom ROM without DSP), [tryCreate] returns null and the * caller falls back to [SoftwareWakeWordDetector]. * * ## How it works * * 1. [tryCreate] uses `Class.forName("android.hardware.soundtrigger.SoundTrigger")` *    to check if the API is available. If not, returns null. * 2. If available, calls `SoundTrigger.listModules()` via reflection to *    enumerate DSP modules. If none found, returns null. * 3. On [start], attaches to the DSP module, loads the keyphrase sound model, *    and starts recognition — all via reflection. * 4. When the DSP detects the keyphrase, the callback fires, we grab the *    2-second audio lead-in from [CircularAudioBuffer], and run Tier 2 *    software confirmation. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§4 Wake Word Detection — 3-Tier DSP-First</a> */class HardwareWakeWordDetector private constructor(    private val context: Context,    private val config: WakeWordDetector.Config,    private val circularBuffer: CircularAudioBuffer,    private val onWakeWordDetected: (WakeWordDetector.WakeWordEvent) -> Unit,    private val soundTriggerClass: Class<*>,    private val modulePropertiesObj: Any,    private val softwareConfirmer: WakeWordSoftwareConfirmer,) : WakeWordDetector {    override val isHardwareAccelerated: Boolean = true    private val running = AtomicBoolean(false)    private var soundTriggerModule: Any? = null  // SoundTrigger.SoundTriggerModule    private var loadedModelId: java.util.UUID? = null    override val isRunning: Boolean get() = running.get()    override fun start() {        if (!running.compareAndSet(false, true)) {            Timber.tag(TAG).w("start() called while already running — ignoring.")            return        }        Timber.tag(TAG).i("Starting hardware wake-word detection on DSP.")        try {            // 1. Attach to the DSP module.            val moduleId = modulePropertiesObj.javaClass.getField("id").getInt(modulePropertiesObj)            val attachMethod = soundTriggerClass.getMethod(                "attachModule",                Int::class.javaPrimitiveType,                Class.forName("android.hardware.soundtrigger.SoundTrigger\$Callback"),                android.os.Handler::class.java,            )            val module = attachMethod.invoke(null, moduleId, soundTriggerCallback, android.os.Handler(android.os.Looper.getMainLooper()))                ?: run {                    Timber.tag(TAG).e("attachModule returned null — aborting.")                    running.set(false)                    return                }            soundTriggerModule = module            // 2. Load the keyphrase sound model.            val modelPath = config.hardwareModelPath ?: run {                Timber.tag(TAG).e("No hardware model path configured — aborting.")                running.set(false)                detachModule(module)                return            }            val modelData = try {                context.assets.open(modelPath).use { it.readBytes() }            } catch (t: Throwable) {                Timber.tag(TAG).e("Failed to load hardware model from $modelPath", t)                running.set(false)                detachModule(module)                return            }            val keyphraseModel = buildKeyphraseModel(modelData) ?: run {                running.set(false)                detachModule(module)                return            }            val loadMethod = module.javaClass.getMethod(                "loadSoundModel",                Class.forName("android.hardware.soundtrigger.SoundTrigger\$SoundModel"),            )            loadedModelId = loadMethod.invoke(module, keyphraseModel) as? java.util.UUID            if (loadedModelId == null) {                Timber.tag(TAG).e("loadSoundModel returned null — aborting.")                running.set(false)                detachModule(module)                return            }            Timber.tag(TAG).i("Sound model loaded: $loadedModelId")            // 3. Start recognition.            val recognitionConfigClass = Class.forName("android.hardware.soundtrigger.SoundTrigger\$RecognitionConfig")            val recognitionConfig = recognitionConfigClass.getConstructor(                Int::class.javaPrimitiveType,                Int::class.javaPrimitiveType,                java.lang.String::class.java,                Class.forName("android.hardware.soundtrigger.SoundTrigger\$KeyphraseRecognitionExtra"),            ).newInstance(1, 0, null, null)  // RECOGNITION_MODE_VOICE_TRIGGER=1            val startMethod = module.javaClass.getMethod(                "startRecognition",                java.util.UUID::class.java,                recognitionConfigClass,            )            startMethod.invoke(module, loadedModelId, recognitionConfig)            Timber.tag(TAG).i("DSP recognition started for model $loadedModelId")        } catch (t: Throwable) {            Timber.tag(TAG).e("Failed to start hardware wake-word detection", t)            running.set(false)            stop()        }    }    override fun stop() {        if (!running.compareAndSet(true, false)) {            return        }        Timber.tag(TAG).i("Stopping hardware wake-word detection.")        val module = soundTriggerModule ?: return        try {            if (loadedModelId != null) {                try {                    val stopMethod = module.javaClass.getMethod("stopRecognition", java.util.UUID::class.java)                    stopMethod.invoke(module, loadedModelId)                } catch (t: Throwable) { Timber.tag(TAG).w("stopRecognition failed", t) }                try {                    val unloadMethod = module.javaClass.getMethod("unloadSoundModel", java.util.UUID::class.java)                    unloadMethod.invoke(module, loadedModelId)                } catch (t: Throwable) { Timber.tag(TAG).w("unloadSoundModel failed", t) }            }            detachModule(module)        } catch (t: Throwable) {            Timber.tag(TAG).w("stop() failed", t)        }        loadedModelId = null        soundTriggerModule = null    }    override fun release() {        stop()    }    private fun detachModule(module: Any) {        try {            val detachMethod = module.javaClass.getMethod("detach")            detachMethod.invoke(module)        } catch (t: Throwable) { Timber.tag(TAG).w("detach failed", t) }    }    // ─── SoundTrigger Callback (via reflection) ───────────────────────────    private val soundTriggerCallback: Any = run {        // Create a proxy for SoundTrigger.Callback using reflection.        // The Callback class has methods: onRecognition, onError, onServiceDied, etc.        val callbackClass = Class.forName("android.hardware.soundtrigger.SoundTrigger\$Callback")        java.lang.reflect.Proxy.newProxyInstance(            callbackClass.classLoader,            arrayOf(callbackClass),        ) { _, method, args ->            when (method.name) {                "onRecognition" -> {                    Timber.tag(TAG).i("DSP detected wake word!")                    handleDetection(args?.firstOrNull())                    null                }                "onError" -> {                    val status = args?.getOrNull(0) as? Int ?: -1                    Timber.tag(TAG).e("SoundTrigger error: status=$status")                    if (running.get()) { stop(); start() }                    null                }                "onServiceDied", "onModuleDied" -> {                    Timber.tag(TAG).e("SoundTrigger $method.name")                    if (running.get()) { stop(); start() }                    null                }                "onRecognitionAvailabilityChanged" -> {                    val available = args?.getOrNull(0) as? Boolean ?: false                    Timber.tag(TAG).i("SoundTrigger availability: $available")                    if (!available && running.get()) stop()                    null                }                else -> null            }        }    }    // ─── Detection Handling ───────────────────────────────────────────────    private fun handleDetection(event: Any?) {        // Get trigger audio from the recognition event (if available).        var triggerAudio: ShortArray? = null        if (event != null) {            try {                val triggerField = event.javaClass.getField("triggerAudio")                triggerAudio = triggerField.get(event) as? ShortArray            } catch (e: Throwable) { Timber.tag("NOUS.Voice").w(e, "SoundTrigger field not found") }        }        // Get the latest audio from the circular buffer for context.        val leadIn = try {            circularBuffer.snapshot()        } catch (e: Throwable) { Timber.tag("NOUS.Voice").w(e, "SoundTrigger method failed"); null }        // Run Tier 2 confirmation.        val confirmed = softwareConfirmer.confirm(triggerAudio, config)        if (confirmed != null) {            Timber.tag(TAG).i("Wake word confirmed by Tier 2 — firing event.")            onWakeWordDetected(confirmed)        } else {            Timber.tag(TAG).i("Tier 2 rejected wake word — restarting DSP.")            val module = soundTriggerModule            if (module != null && loadedModelId != null && running.get()) {                try {                    val recognitionConfigClass = Class.forName("android.hardware.soundtrigger.SoundTrigger\$RecognitionConfig")                    val recognitionConfig = recognitionConfigClass.getConstructor(                        Int::class.javaPrimitiveType, Int::class.javaPrimitiveType,                        java.lang.String::class.java,                        Class.forName("android.hardware.soundtrigger.SoundTrigger\$KeyphraseRecognitionExtra"),                    ).newInstance(1, 0, null, null)                    val startMethod = module.javaClass.getMethod("startRecognition", java.util.UUID::class.java, recognitionConfigClass)                    startMethod.invoke(module, loadedModelId, recognitionConfig)                } catch (t: Throwable) {                    Timber.tag(TAG).e("Failed to restart DSP recognition", t)                }            }        }    }    // ─── Sound Model Building ─────────────────────────────────────────────    private fun buildKeyphraseModel(modelData: ByteArray): Any? {        return try {            val keyphraseClass = Class.forName("android.hardware.soundtrigger.SoundTrigger\$Keyphrase")            val keyphrase = keyphraseClass.getConstructor(                Int::class.javaPrimitiveType,                java.lang.String::class.java,                java.lang.String::class.java,            ).newInstance(1, java.util.Locale.getDefault().toLanguageTag(), config.keyphrase)            val keyphraseModelClass = Class.forName("android.hardware.soundtrigger.SoundTrigger\$KeyphraseSoundModel")            keyphraseModelClass.getConstructor(                java.util.UUID::class.java,                java.util.UUID::class.java,                ByteArray::class.java,                java.lang.reflect.Array.newInstance(keyphraseClass, 0).javaClass,            ).newInstance(                java.util.UUID.randomUUID(),                null,                modelData,                java.lang.reflect.Array.newInstance(keyphraseClass, 1).also { java.lang.reflect.Array.set(it, 0, keyphrase) },            )        } catch (t: Throwable) {            Timber.tag(TAG).e("Failed to build keyphrase sound model", t)            null        }    }    // ─── Factory ──────────────────────────────────────────────────────────    companion object {        private const val TAG = "HardwareWakeWord"        /**         * Probe the device for DSP hotword support.         *         * Uses reflection to check if SoundTrigger API is available at runtime.         * Returns null if:         *   - SoundTrigger class not found (API not on this device)         *   - listModules() returns empty (no DSP hardware)         *   - Any reflection error occurs         *         * Caller falls back to [SoftwareWakeWordDetector] when this returns null.         */        fun tryCreate(            context: Context,            config: WakeWordDetector.Config,            circularBuffer: CircularAudioBuffer,            onWakeWordDetected: (WakeWordDetector.WakeWordEvent) -> Unit,        ): HardwareWakeWordDetector? {            return try {                // 1. Check if SoundTrigger class exists at runtime.                val stClass = Class.forName("android.hardware.soundtrigger.SoundTrigger")                    ?: return null                // 2. Call SoundTrigger.listModules() via reflection.                val listModulesMethod = stClass.getMethod("listModules")                @Suppress("UNCHECKED_CAST")                val modules = listModulesMethod.invoke(null) as? List<Any>                if (modules.isNullOrEmpty()) {                    Timber.tag(TAG).i("No SoundTrigger modules on this device.")                    return null                }                val moduleProps = modules[0]                Timber.tag(TAG).i("SoundTrigger module found (via reflection).")                HardwareWakeWordDetector(                    context = context,                    config = config,                    circularBuffer = circularBuffer,                    onWakeWordDetected = onWakeWordDetected,                    soundTriggerClass = stClass,                    modulePropertiesObj = moduleProps,                    softwareConfirmer = WakeWordSoftwareConfirmer.Impl,                )            } catch (e: ClassNotFoundException) {                Timber.tag(TAG).i("SoundTrigger API not available on this device — using software detection.")                null            } catch (t: Throwable) {                Timber.tag(TAG).w("SoundTrigger not available: ${t.message}")                null            }        }    }}